  Lemma hdr6_entry : forall A vm vals R M buf cap j,
    length vals = 41%nat -> slots vals buf L cap ->
    regs_ok (ENV vals) sr_H R -> know_ok RSEGS (ENV vals) M kn_ML -> side A vm M buf cap j -> bytes_at M (bv_unsigned buf) data ->
